import {IANA_TLDS} from './iana-tlds';

const EMAIL_LOCAL_PATTERN = /^[a-zA-Z0-9._%+-]+$/;
const EMAIL_DOMAIN_LABEL_PATTERN =
  /^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$/;

export const isValidEmail = (value: string): boolean => {
  const normalizedEmail = value.trim();
  if (normalizedEmail === '' || /\s/.test(normalizedEmail)) {
    return false;
  }
  if ((normalizedEmail.match(/@/g) || []).length !== 1) {
    return false;
  }

  const [localPart, domainPart] = normalizedEmail.split('@');
  if (!localPart || !domainPart) {
    return false;
  }
  if (localPart.length > 64 || domainPart.length > 253) {
    return false;
  }
  if (
    localPart.startsWith('.') ||
    localPart.endsWith('.') ||
    localPart.includes('..') ||
    !EMAIL_LOCAL_PATTERN.test(localPart)
  ) {
    return false;
  }

  const labels = domainPart.split('.');
  if (labels.length < 2) {
    return false;
  }
  if (labels.some((label) => !EMAIL_DOMAIN_LABEL_PATTERN.test(label))) {
    return false;
  }

  const tld = labels[labels.length - 1].toLowerCase();
  return IANA_TLDS.has(tld);
};

